#!/usr/bin/env bash
# skill-eval-setup.sh — build the sandbox a skill evaluation runs in.
#
# Two artefacts, in a throwaway directory:
#   SKILL.md   generated by `uku setup agents` into a scratch HOME, so the
#              evaluation reads exactly the bytes a user receives — not the
#              heredoc in bin/uku, which is one edit away from differing.
#   bin/uku    a mock that RECORDS ARGV AND WRITES NOTHING. The point of the
#              exercise is which commands the model chooses; letting it reach a
#              real account would risk a real invoice to learn a prose lesson.
#
# See skill-evals/README.md for how to run a case and how to grade it.
set -euo pipefail

repo="$(cd "$(dirname "$0")/.." && pwd)"
out="${1:-${TMPDIR:-/tmp}/uku-skill-eval}"

rm -rf "$out"
mkdir -p "$out/bin"

# ── the skill, as a user receives it ─────────────────────────────────
scratch="$(mktemp -d)"
trap 'rm -rf "$scratch"' EXIT
HOME="$scratch" UKU_CONFIG_HOME="$scratch/cfg" UKU_SETUP_AGENT=claude \
  bash "$repo/bin/uku" setup agents >/dev/null 2>&1 || true

skill="$(find "$scratch" -name SKILL.md -print 2>/dev/null | head -n 1)"
[ -n "$skill" ] || { printf 'could not generate SKILL.md via `uku setup agents`\n' >&2; exit 1; }
cp "$skill" "$out/SKILL.md"

# ── the mock ─────────────────────────────────────────────────────────
# Answers are plausible but fixed. Two clients share a prefix on purpose: that
# is the ambiguity case. Nothing here validates input — the mock cannot tell a
# real command from an invented one, so a case that passes against the mock has
# only proved the model's INTENT. Whether the CLI accepts the command is what
# bin/ci is for.
cat > "$out/bin/uku" <<'MOCK'
#!/bin/bash
printf '%s\n' "$*" >> "${UKU_EVAL_LOG:?set UKU_EVAL_LOG}"
case "$*" in
  *"auth status"*|*" me"*) echo '{"data":{"name":"Test User","company":"Demo OU"}}' ;;
  *"account current"*)     echo 'main' ;;
  *"account list"*)        echo '● main'; echo '  sandbox' ;;
  *"clients list"*)        echo '{"data":[{"id":41,"name":"Acme Ltd"},{"id":42,"name":"Acme Holdings"}],"meta":{"total":2}}' ;;
  *"clients get"*)         echo '{"data":{"id":41,"name":"Acme Ltd"}}' ;;
  *"tasks list"*)          echo '{"data":[{"id":7,"title":"Käibedeklaratsioon","status":"open","client_id":41}],"meta":{"total":1}}' ;;
  *"time list"*)           echo '{"data":[{"id":3,"task_id":7,"duration":60}],"meta":{"total":1}}' ;;
  *"invoices list"*)       echo '{"data":[{"id":88,"status":"draft","client_id":41}],"meta":{"total":1}}' ;;
  *"invoices get"*)        echo '{"data":{"id":88,"status":"draft","client_id":41}}' ;;
  *create*|*patch*|*send*|*"mark-paid"*) echo '{"data":{"id":999}}' ;;
  *)                       echo '{"data":[],"meta":{"total":0}}' ;;
esac
exit 0
MOCK
chmod +x "$out/bin/uku"
: > "$out/commands.log"

cat <<EOF
skill-eval sandbox ready: $out

  SKILL.md      $(wc -l < "$out/SKILL.md" | tr -d ' ') lines, as \`uku setup agents\` writes it
  bin/uku       mock — records argv, writes nothing
  commands.log  where the chosen commands land

Hand a subagent one file from skill-evals/cases/, and tell it:
  - read $out/SKILL.md, and read nothing else about uku
  - export PATH=$out/bin:\$PATH
  - export UKU_EVAL_LOG=$out/commands.log

Then grade $out/commands.log against the case's accept/reject lines.
EOF
